function Template(
  args: Omit<ItemProps, 'endAdornment' | 'startAdornment'> & {
    dense: boolean
    endAdornment: EndAdornmentOptions
    startAdornment: StartAdornmentOptions
    subheader: string
  },
): JSX.Element {
  const [checked, setChecked] = useReducer(
    (
      state: { [key: string]: boolean },
      newState: { [key: string]: boolean },
    ) => {
      if (args.startAdornment === 'Checkbox') {
        return { ...state, ...newState }
      }
      return { ...newState }
    },
    {},
  )

  const props = { ...args, endAdornment: undefined, startAdornment: undefined }

  const handleToggle = (id: string) => {
    setChecked({ [id]: !checked[id] })
  }

  const end = adornments[args.endAdornment]
  const endType = endAdornments[args.endAdornment]

  const start = adornments[args.startAdornment]
  const startType = startAdornments[args.startAdornment]

  return (
    <div className="flex max-h-full bg-white-100">
      <List dense={args.dense} subheader={args.subheader}>
        {rows.map((item) => {
          const selected = checked[item.id]

          return (
            <List.Item
              {...props}
              aria-label="people"
              disabled={item.disabled}
              endAdornment={end}
              endAdornmentType={endType}
              key={item.id}
              onClick={() => handleToggle(item.id)}
              primary={args.primary || item.primary}
              secondary={args.secondary || item.secondary}
              selected={selected}
              startAdornment={start}
              startAdornmentType={startType}
            />
          )
        })}
      </List>
    </div>
  )
}

